void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec4 swirl = texture(iChannel0, uv);
    vec4 env = texture(iChannel1, uv);
    vec4 particles = texture(iChannel2, uv);
    vec3 col = mix(swirl.rgb*1.3, env.rgb, 0.1);
    col = mix(col, particles.rgb, 0.5);
    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;
    float t = iTime;
    float angle = atan(uv.y, uv.x);
    float radius = length(uv);
    float swirl = sin(6.0 * angle + t * 1.5 + radius * 10.0);
    vec3 color = vec3(
        swirl * 0.4 + 0.6,
        swirl * 0.2 + 0.8,
        swirl * 0.15 + 0.85
    );
    fragColor = vec4(color, 1.0);
}

vec3 getSky(vec2 uv)
{
vec4 mouse=iMouse;
if (iMouse.x == 0.0) {

    mouse = vec4(.25*iResolution.x,.45*iResolution.y,0.0,0.0);
} 
    float atmosphere = sqrt(1.0-uv.y);
    vec3 skyColor = vec3(0.0,0.1,0.99);

    float scatter = pow(mouse.y / iResolution.y,1.0 / 15.0);
    scatter = 1.0 - clamp(scatter,0.8,1.0);

    vec3 scatterColor = mix(vec3(.4,.5,.99),vec3(0.2,0.3,1.0) * 1.5,scatter);
    return mix(skyColor,vec3(scatterColor),atmosphere / 0.7);

}

vec3 getSun(vec2 uv){
vec4 mouse=iMouse;
if (iMouse.x == 0.0) {
    mouse = vec4(.25*iResolution.x,.45*iResolution.y,0.0,0.0);
} 

	float sun = 1.0 - distance(uv,mouse.xy / iResolution.y);
    sun = clamp(sun,0.0,1.0);

    float glow = sun;
    glow = clamp(glow,0.0,1.0);

    sun = pow(sun,100.0);
    sun *= 100.0;
    sun = clamp(sun,0.0,1.0);

    glow = pow(glow,6.0) * 1.0;
    glow = pow(glow,(uv.y));
    glow = clamp(glow,0.0,1.0);

    sun *= pow(dot(uv.y, uv.y), 1.0 / 1.65);

    glow *= pow(dot(uv.y, uv.y), 1.0 / 2.0);

    sun += glow;

    vec3 sunColor = vec3(6.0,4.6,0.05) * sun;

    return vec3(sunColor);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = fragCoord.xy / iResolution.y;

    vec3 sky = getSky(uv);
    vec3 sun = getSun(uv);

	fragColor = vec4(sky + sun,1.0);
}

#define PI 3.14159265359

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;
    float time = iTime * 0.1935 + 20.0;
    vec3 color = vec3(0.0);
    float heartBeat = abs(sin(iTime * 0.02)) * 0.03 + 0.7;
    float scale = 1.0 + heartBeat * 0.1;
    int NUM_PARTICLES = 19;

    for(int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime = id * 0.8909090908097069756865754653435;
        float theta = particleTime * 30.14 * sin(time / 7.0) * PI;
        float phi = acos(1.0 - 2.2 * particleTime);
        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * sin(theta),
            cos(phi)
        );
        float angle = time * 0.4;
        mat3 rotation = mat3(
            cos(angle), 0.0, -sin(angle),
            0.0,        1.0,  0.0,
            sin(angle), 0.0,  cos(angle)
        );
        spherePos = rotation * spherePos;
        vec2 screenPos = spherePos.xy / (spherePos.z + 2.2) * scale;
        float dist = length(uv - screenPos);
        float viscosity = exp(-dist * 3.0) * (0.1 + heartBeat * 0.2);
        vec3 particleColor = vec3(
            0.5 + 0.5 * sin(time + id * 16.28),
            0.5 + 0.5 * sin(time + id * 6.28 + PI / 3.0),
            0.5 + 0.5 * sin(time + id * 6.28 + 2.0 * PI / 3.0)
        );
        color += particleColor * viscosity;
    }

    float intensity = color.r * color.g * color.b;
    if (intensity > .01112) {
        fragColor = vec4(color.rgb* 01.740 *(intensity),1.0);
    } else if (intensity < 0.3) {
        fragColor = vec4(.5 - color.gbr * vec3(exp(intensity * 10.10)), 1.0);
    } else {
       fragColor =  vec4(color.rgb * exp(-intensity*124.0), 1.0);
       fragColor = vec4(  color.rgb * intensity , 1.0);
    }
}
